// apps/backend/src/services/document.service.ts
import fs4 from "node:fs/promises";
import { PDFParse } from "pdf-parse";

// apps/backend/src/middlewares/upload.ts
import multer from "multer";
import path3 from "node:path";
import crypto10 from "node:crypto";
var UPLOAD_DIR = path3.resolve("uploads");
var MAX_FILE_SIZE = 10 * 1024 * 1024;
var ALLOWED_MIMES = {
  "application/pdf": "PDF",
  "text/plain": "TXT",
  "text/markdown": "MARKDOWN",
  "text/html": "HTML"
};
var storage = multer.diskStorage({
  destination: (_req, _file, cb) => cb(null, UPLOAD_DIR),
  filename: (_req, file, cb) => {
    const ext = path3.extname(file.originalname);
    cb(null, `${crypto10.randomUUID()}${ext}`);
  }
});
var upload = multer({
  storage,
  limits: { fileSize: MAX_FILE_SIZE },
  fileFilter: (_req, file, cb) => {
    if (!ALLOWED_MIMES[file.mimetype]) {
      cb(new AppError(400, "INVALID_FILE_TYPE", "Tipo de arquivo n\xE3o suportado. Use PDF, TXT, MD ou HTML."));
      return;
    }
    cb(null, true);
  }
});
function mimeToDocType(mime) {
  return ALLOWED_MIMES[mime] ?? "TXT";
}

// apps/backend/src/utils/text-encoding.ts
function decodeTextBuffer(buffer) {
  const utf8 = buffer.toString("utf-8");
  if (utf8.includes("\uFFFD")) {
    return buffer.toString("latin1");
  }
  return utf8;
}

// apps/backend/src/utils/document-kind.ts
var DOCUMENT_KINDS = [
  "EDITAL",
  "EMENTA",
  "CRONOGRAMA",
  "MATERIAL",
  "LISTA_QUESTOES",
  "OUTRO"
];
var SIGNALS = {
  EDITAL: [
    /\bedital\b/i,
    /concurso\s+p[úu]blico/i,
    /processo\s+seletivo/i,
    /\bvagas?\b/i,
    /\binscri[çc][õo]es\b/i,
    /\bbanca\b/i,
    /\bremunera[çc][ãa]o\b/i,
    /\bcargo\b/i
  ],
  EMENTA: [
    /\bementa\b/i,
    /plano\s+de\s+ensino/i,
    /\bbibliografia\b/i,
    /carga\s+hor[áa]ria/i,
    /unidade\s+curricular/i,
    /\bdisciplina\b/i,
    /objetivos\s+de\s+aprendizagem/i
  ],
  CRONOGRAMA: [
    /\bcronograma\b/i,
    /\bcalend[áa]rio\b/i,
    /semana\s*\d+/i,
    /\bsegunda\b.*\bter[çc]a\b/i,
    /\d{1,2}\s*[/-]\s*\d{1,2}/
  ],
  LISTA_QUESTOES: [
    /\bgabarito\b/i,
    /\balternativas?\b/i,
    /quest[ãa]o\s*\d+/i,
    /\(\s*[a-eA-E]\s*\)/,
    /\bresposta\s+correta\b/i
  ],
  MATERIAL: [/\bresumo\b/i, /\bap[oó]stila\b/i, /\bcap[íi]tulo\b/i, /\bconceito\b/i, /\bintrodu[çc][ãa]o\b/i]
};
function detectDocumentKind(text) {
  const sample = text.slice(0, 6e3);
  let best = "OUTRO";
  let bestScore = 0;
  for (const kind of Object.keys(SIGNALS)) {
    const score = SIGNALS[kind].reduce((acc, re) => acc + (re.test(sample) ? 1 : 0), 0);
    if (score > bestScore) {
      bestScore = score;
      best = kind;
    }
  }
  return bestScore >= 2 ? best : "OUTRO";
}

// apps/backend/src/services/document.service.ts
var DocumentService = class {
  async upload(userId, file, subjectId, kind) {
    if (subjectId) {
      const subject = await prisma.subject.findUnique({ where: { id: subjectId } });
      if (!subject) {
        throw new AppError(404, "SUBJECT_NOT_FOUND", "Disciplina n\xE3o encontrada");
      }
    }
    const content = await this.extractText(file);
    const docType = mimeToDocType(file.mimetype);
    const suggestedKind = detectDocumentKind(content);
    const finalKind = kind ?? suggestedKind;
    const document = await prisma.document.create({
      data: {
        userId,
        name: file.originalname,
        type: docType,
        kind: finalKind,
        content,
        subjectId: subjectId ?? null
      }
    });
    await fs4.unlink(file.path).catch(() => {
    });
    return { ...document, suggestedKind, kindAutoDetected: !kind };
  }
  async updateKind(userId, id, kind) {
    if (!DOCUMENT_KINDS.includes(kind)) {
      throw new AppError(400, "INVALID_KIND", "Tipo de documento inv\xE1lido");
    }
    const doc = await prisma.document.findUnique({ where: { id } });
    if (!doc || doc.userId !== userId) {
      throw new AppError(404, "DOCUMENT_NOT_FOUND", "Documento n\xE3o encontrado");
    }
    return prisma.document.update({ where: { id }, data: { kind } });
  }
  async list(userId, subjectId) {
    return prisma.document.findMany({
      where: { userId, ...subjectId ? { subjectId } : {} },
      orderBy: { createdAt: "desc" },
      select: {
        id: true,
        name: true,
        type: true,
        kind: true,
        subjectId: true,
        createdAt: true,
        content: false
      }
    });
  }
  async getById(userId, id) {
    const doc = await prisma.document.findUnique({ where: { id } });
    if (!doc || doc.userId !== userId) {
      throw new AppError(404, "DOCUMENT_NOT_FOUND", "Documento n\xE3o encontrado");
    }
    return doc;
  }
  async delete(userId, id) {
    const doc = await prisma.document.findUnique({ where: { id } });
    if (!doc || doc.userId !== userId) {
      throw new AppError(404, "DOCUMENT_NOT_FOUND", "Documento n\xE3o encontrado");
    }
    await prisma.document.delete({ where: { id } });
  }
  async getContentBySubject(subjectId, maxChars = 8e3) {
    const docs = await prisma.document.findMany({
      where: { subjectId },
      orderBy: { createdAt: "desc" },
      select: { content: true, name: true },
      take: 5
    });
    if (docs.length === 0) return "";
    let combined = "";
    for (const doc of docs) {
      const chunk = `--- ${doc.name} ---
${doc.content}

`;
      if (combined.length + chunk.length > maxChars) {
        combined += chunk.slice(0, maxChars - combined.length);
        break;
      }
      combined += chunk;
    }
    return combined;
  }
  async extractText(file) {
    if (file.mimetype === "application/pdf") {
      const data = await fs4.readFile(file.path);
      const parser = new PDFParse({ data: new Uint8Array(data) });
      await parser.load();
      const result = await parser.getText();
      return result.text.trim();
    }
    const buffer = await fs4.readFile(file.path);
    return decodeTextBuffer(buffer).trim();
  }
};

// apps/backend/src/utils/html.ts
function htmlToPlainText(input) {
  if (!input) return "";
  return input.replace(/<\s*br\s*\/?\s*>/gi, "\n").replace(/<\s*\/\s*(p|div|li|tr)\s*>/gi, "\n").replace(/<\s*li[^>]*>/gi, "\u2022 ").replace(/<[^>]+>/g, "").replace(/&nbsp;/gi, " ").replace(/&amp;/gi, "&").replace(/&lt;/gi, "<").replace(/&gt;/gi, ">").replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
}

