function buildAuditPrompt(params) {
  const subjectBlock = params.subject ? ` de ${params.subject}` : "";
  const blocks = params.questions.map((q, i) => {
    const alts = q.alternatives.map((a) => `${a.letter}) ${a.text}`).join("\n");
    return `[index ${i}]
${q.statement}
${alts}`;
  }).join("\n\n");
  return `Voc\xEA \xE9 um candidato experiente resolvendo uma prova de concurso${subjectBlock}. Resolva CADA quest\xE3o escolhendo a \xDANICA alternativa correta, usando apenas seu conhecimento t\xE9cnico. N\xE3o explique, n\xE3o comente \u2014 apenas escolha.

${blocks}

Responda APENAS com JSON v\xE1lido, sem markdown, uma resposta por quest\xE3o (use o index informado):
{ "answers": [ { "index": 0, "letter": "A" } ] }`;
}
function mapAuditAnswers(parsed, count) {
  const out = new Array(count).fill("");
  for (const a of parsed.answers) {
    if (a.index >= 0 && a.index < count) {
      out[a.index] = a.letter.trim().charAt(0).toUpperCase();
    }
  }
  return out;
}
function stripJsonMarkdown(raw2) {
  return raw2.replace(/```json\n?/g, "").replace(/```\n?/g, "").trim();
}

// apps/backend/src/providers/resilience/circuit-breaker.ts
var CircuitBreaker = class {
  state = "closed";
  failures = 0;
  successes = 0;
  nextAttempt = Date.now();
  config;
  serviceName;
  constructor(serviceName, config) {
    this.serviceName = serviceName;
    this.config = {
      failureThreshold: config?.failureThreshold ?? 3,
      successThreshold: config?.successThreshold ?? 2,
      timeoutMs: config?.timeoutMs ?? 3e4
    };
  }
  async execute(action) {
    if (this.state === "open") {
      if (Date.now() > this.nextAttempt) {
        this.state = "half-open";
      } else {
        throw new Error(
          `O servi\xE7o de IA [${this.serviceName}] est\xE1 temporariamente em resguardo devido a erros recentes. Tente novamente em alguns segundos.`
        );
      }
    }
    try {
      const result = await action();
      this.onSuccess();
      return result;
    } catch (error2) {
      this.onFailure();
      throw error2;
    }
  }
  onSuccess() {
    if (this.state === "half-open") {
      this.successes += 1;
      if (this.successes >= this.config.successThreshold) {
        this.state = "closed";
        this.failures = 0;
        this.successes = 0;
      }
    } else {
      this.failures = 0;
    }
  }
  onFailure() {
    this.failures += 1;
    if (this.state === "half-open" || this.failures >= this.config.failureThreshold) {
      this.state = "open";
      this.nextAttempt = Date.now() + this.config.timeoutMs;
    }
  }
  getState() {
    return this.state;
  }
};

// apps/backend/src/providers/resilience/concurrency-queue.ts
var ConcurrencyQueue = class {
  config;
  queue = [];
  activeCount = 0;
  completedCount = 0;
  failedCount = 0;
  constructor(config) {
    this.config = {
      maxConcurrent: config?.maxConcurrent ?? 4,
      maxQueueSize: config?.maxQueueSize ?? 20,
      timeoutMs: config?.timeoutMs ?? 6e4
    };
  }
  async enqueue(operation, priority = "normal") {
    if (this.queue.length >= this.config.maxQueueSize) {
      throw new Error("Fila de processamento da IA sobrecarregada. Aguarde alguns instantes.");
    }
    return new Promise((resolve3, reject) => {
      const item = {
        operation,
        resolve: resolve3,
        reject,
        priority,
        timestamp: Date.now()
      };
      if (priority === "high") {
        let lastHighIndex = -1;
        for (let i = this.queue.length - 1; i >= 0; i -= 1) {
          if (this.queue[i]?.priority === "high") {
            lastHighIndex = i;
            break;
          }
        }
        if (lastHighIndex === -1) {
          this.queue.unshift(item);
        } else {
          this.queue.splice(lastHighIndex + 1, 0, item);
        }
      } else {
        this.queue.push(item);
      }
      this.processNext();
    });
  }
  processNext() {
    if (this.activeCount >= this.config.maxConcurrent || this.queue.length === 0) {
      return;
    }
    const item = this.queue.shift();
    if (!item) return;
    this.activeCount += 1;
    const timeoutPromise = new Promise((_, reject) => {
      setTimeout(() => reject(new Error("Tempo limite de resposta da IA excedido.")), this.config.timeoutMs);
    });
    Promise.race([item.operation(), timeoutPromise]).then((result) => {
      this.completedCount += 1;
      item.resolve(result);
    }).catch((error2) => {
      this.failedCount += 1;
      item.reject(error2);
    }).finally(() => {
      this.activeCount -= 1;
      this.processNext();
    });
  }
  getStatus() {
    return {
      running: this.activeCount,
      queued: this.queue.length,
      completed: this.completedCount,
      failed: this.failedCount
    };
  }
};

// apps/backend/src/providers/resilience/retry-strategy.ts
var DEFAULT_CONFIG = {
  maxAttempts: 3,
  initialDelayMs: 1e3,
  maxDelayMs: 1e4,
  backoffMultiplier: 2,
  retryableErrors: [429, 503, 504]
};
var RetryStrategy = class {
  config;
  constructor(config) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }
  async execute(action, onRetry) {
    let attempt = 1;
    while (attempt <= this.config.maxAttempts) {
      try {
        return await action();
      } catch (error2) {
        if (attempt >= this.config.maxAttempts || !this.isRetryable(error2)) {
          throw error2;
        }
        if (onRetry) {
          onRetry(attempt, this.config.maxAttempts);
        }
        const delay = this.calculateDelay(attempt);
        await new Promise((resolve3) => setTimeout(resolve3, delay));
        attempt += 1;
      }
    }
    throw new Error("N\xFAmero m\xE1ximo de tentativas de chamada excedido.");
  }
  isRetryable(error2) {
    if (error2 && typeof error2 === "object" && "status" in error2) {
      const status = error2.status;
      if (typeof status === "number") {
        return this.config.retryableErrors.includes(status);
      }
    }
    if (error2 instanceof Error) {
      return this.config.retryableErrors.some((code) => error2.message.includes(code.toString()));
    }
    return false;
  }
  calculateDelay(attempt) {
    const baseDelay = this.config.initialDelayMs * Math.pow(this.config.backoffMultiplier, attempt - 1);
    const cappedDelay = Math.min(baseDelay, this.config.maxDelayMs);
    const jitter = cappedDelay * 0.2;
    const randomJitter = (Math.random() * 2 - 1) * jitter;
    return Math.floor(cappedDelay + randomJitter);
  }
};

