async function requireAdmin(req, res, next) {
  try {
    const user = await prisma.user.findUnique({
      where: { id: getUserId(req) },
      select: { role: true }
    });
    if (user?.role === "ADMIN") {
      return next();
    }
    return res.status(403).json({
      success: false,
      error: { message: "Acesso restrito ao administrador.", code: "ADMIN_ONLY" }
    });
  } catch (error2) {
    next(error2);
  }
}

