var FALLBACK_SUBJECT2 = "Geral";
var QuestionSetService = class {
  questionService;
  constructor(aiProvider4) {
    this.questionService = new QuestionService(aiProvider4);
  }
  async list(userId) {
    const sets = await prisma.questionSet.findMany({
      where: { userId },
      orderBy: [{ lastAttemptAt: "desc" }, { createdAt: "desc" }],
      include: {
        subject: { select: { id: true, name: true } },
        items: { select: { questionId: true } }
      }
    });
    return Promise.all(
      sets.map(async (s) => {
        const qIds = s.items.map((i) => i.questionId);
        const answered = qIds.length ? await this.countAnswered(userId, qIds) : 0;
        return {
          id: s.id,
          name: s.name,
          mode: s.mode,
          questionType: s.questionType,
          subject: s.subject,
          createdAt: s.createdAt,
          lastAttemptAt: s.lastAttemptAt,
          total: qIds.length,
          answered
        };
      })
    );
  }
  async generate(userId, dto) {
    const subject = await this.resolveSubject(dto.subjectId);
    const questions = await this.questionService.generate(userId, {
      subjectId: subject.id,
      quantity: dto.quantity,
      examBoardId: dto.examBoardId,
      difficulty: dto.difficulty,
      topic: dto.topic,
      documentId: dto.documentId,
      content: dto.content,
      questionType: dto.questionType,
      cloneStyle: dto.cloneStyle
    });
    if (questions.length === 0) {
      throw new AppError(400, "NO_QUESTIONS", "N\xE3o foi poss\xEDvel gerar quest\xF5es para esta configura\xE7\xE3o.");
    }
    return prisma.questionSet.create({
      data: {
        userId,
        name: dto.name?.trim() || this.defaultName(subject.name),
        subjectId: subject.id,
        mode: dto.mode ?? "STUDY",
        questionType: dto.questionType ?? "MULTIPLE_5",
        items: { create: questions.map((q, i) => ({ questionId: q.id, order: i })) }
      },
      select: { id: true, name: true }
    });
  }
  async createManual(userId, dto) {
    const subject = await this.resolveSubject(dto.subjectId);
    const created = await prisma.$transaction(
      dto.questions.map(
        (q) => prisma.question.create({
          data: {
            statement: q.statement,
            alternatives: q.alternatives,
            correctAnswer: q.alternatives.length === 0 ? ESSAY_ANSWER : q.correctAnswer ?? "",
            explanation: q.explanation ?? "",
            difficulty: q.difficulty,
            comments: [],
            subjectId: subject.id,
            source: "MANUAL"
          },
          select: { id: true }
        })
      )
    );
    return prisma.questionSet.create({
      data: {
        userId,
        name: dto.name.trim(),
        subjectId: subject.id,
        mode: dto.mode ?? "STUDY",
        questionType: dto.questionType ?? "MULTIPLE_5",
        items: { create: created.map((c, i) => ({ questionId: c.id, order: i })) }
      },
      select: { id: true, name: true }
    });
  }
  async rename(userId, id, name2) {
    await this.ownedSet(userId, id);
    return prisma.questionSet.update({ where: { id }, data: { name: name2.trim() }, select: { id: true, name: true } });
  }
  async getById(userId, id) {
    await this.ownedSet(userId, id);
    const set = await prisma.questionSet.update({
      where: { id },
      data: { lastAttemptAt: /* @__PURE__ */ new Date() },
      include: {
        items: {
          orderBy: { order: "asc" },
          include: { question: { include: { subject: true, examBoard: true } } }
        }
      }
    });
    return {
      id: set.id,
      name: set.name,
      mode: set.mode,
      questions: set.items.map((i) => i.question)
    };
  }
  async delete(userId, id) {
    await this.ownedSet(userId, id);
    await prisma.questionSet.delete({ where: { id } });
  }
  async ownedSet(userId, id) {
    const set = await prisma.questionSet.findUnique({ where: { id }, select: { userId: true } });
    if (!set || set.userId !== userId) {
      throw new AppError(404, "SET_NOT_FOUND", "Simulado n\xE3o encontrado");
    }
  }
  async countAnswered(userId, questionIds) {
    const distinct = await prisma.questionAttempt.findMany({
      where: { userId, questionId: { in: questionIds } },
      distinct: ["questionId"],
      select: { questionId: true }
    });
    return distinct.length;
  }
  // Matéria é opcional: sem ela, usa (ou cria) uma matéria "Geral"
  async resolveSubject(subjectId) {
    if (subjectId) {
      const subject = await prisma.subject.findUnique({ where: { id: subjectId } });
      if (!subject) throw new AppError(404, "SUBJECT_NOT_FOUND", "Disciplina n\xE3o encontrada");
      return subject;
    }
    const existing = await prisma.subject.findFirst({ where: { name: FALLBACK_SUBJECT2, parentId: null } });
    return existing ?? prisma.subject.create({ data: { name: FALLBACK_SUBJECT2 } });
  }
  defaultName(subjectName) {
    const date = (/* @__PURE__ */ new Date()).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
    return `${subjectName} - ${date}`;
  }
};

