// apps/backend/src/utils/ical-generator.ts
function escapeText(text) {
  return text.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
}
function formatUtcDate(date) {
  const pad = (n) => String(n).padStart(2, "0");
  const year = date.getUTCFullYear();
  const month = pad(date.getUTCMonth() + 1);
  const day = pad(date.getUTCDate());
  const hours = pad(date.getUTCHours());
  const minutes = pad(date.getUTCMinutes());
  const seconds = pad(date.getUTCSeconds());
  return `${year}${month}${day}T${hours}${minutes}${seconds}Z`;
}
function formatAllDayDate(date) {
  const pad = (n) => String(n).padStart(2, "0");
  const year = date.getFullYear();
  const month = pad(date.getMonth() + 1);
  const day = pad(date.getDate());
  return `${year}${month}${day}`;
}
var ICalGenerator = class {
  calendarName;
  events = [];
  constructor(calendarName = "Engrama - Cronograma de Estudos") {
    this.calendarName = calendarName;
  }
  addEvent(event) {
    this.events.push(event);
    return this;
  }
  build() {
    const lines = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//Engrama//Calendario de Estudos//PT",
      "CALSCALE:GREGORIAN",
      "METHOD:PUBLISH",
      `X-WR-CALNAME:${escapeText(this.calendarName)}`,
      "X-WR-TIMEZONE:America/Sao_Paulo"
    ];
    const nowUtc = formatUtcDate(/* @__PURE__ */ new Date());
    for (const event of this.events) {
      lines.push("BEGIN:VEVENT");
      lines.push(`UID:${event.uid}`);
      lines.push(`DTSTAMP:${nowUtc}`);
      if (event.isAllDay) {
        const dateStr = formatAllDayDate(event.startDate);
        lines.push(`DTSTART;VALUE=DATE:${dateStr}`);
        const nextDay = new Date(event.startDate);
        nextDay.setDate(nextDay.getDate() + 1);
        lines.push(`DTEND;VALUE=DATE:${formatAllDayDate(nextDay)}`);
      } else {
        lines.push(`DTSTART:${formatUtcDate(event.startDate)}`);
        const endDate = event.endDate ?? new Date(event.startDate.getTime() + (event.durationMinutes ?? 30) * 6e4);
        lines.push(`DTEND:${formatUtcDate(endDate)}`);
      }
      lines.push(`SUMMARY:${escapeText(event.summary)}`);
      if (event.description) {
        lines.push(`DESCRIPTION:${escapeText(event.description)}`);
      }
      lines.push(`STATUS:${event.status ?? "CONFIRMED"}`);
      lines.push("END:VEVENT");
    }
    lines.push("END:VCALENDAR");
    return lines.join("\r\n");
  }
};

